extern "C" __global__ void silu_mul_combo(const float* __restrict__ h1, float* __restrict__ h2,
                                          const int* __restrict__ n640_p) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= *n640_p) return;
    int c = i / 640;
    int j = i % 640;
